#!/usr/bin/env -S deno run --allow-read --allow-write --allow-run=git
/**
 * Generate plugin index files from manifests.
 * Creates JSON and Markdown outputs for API and documentation.
 * Note: Individual mod pages are generated by Lume directly from manifests.
 */

import { Command } from "@cliffy/command"
import { sortBy } from "@std/collections"
import * as YAML from "@std/yaml"
import { walk } from "@std/fs"
import { dirname, relative } from "@std/path"
import { ModManifest } from "../schema/manifest.ts"
import { toJsonSchema } from "@valibot/to-json-schema"
import * as v from "valibot"

const DEFAULT_ICON =
  "https://raw.githubusercontent.com/cataclysmbn/Cataclysm-BN/main/gfx/app_icon/app-icon.svg"

const textDecoder = new TextDecoder()

const getManifestGitTimestamp = async (
  registryIndexDir: string,
  manifestPath: string,
): Promise<string | undefined> => {
  try {
    const output = await new Deno.Command("git", {
      args: ["-C", registryIndexDir, "log", "-1", "--format=%cI", "--", manifestPath],
      stdout: "piped",
      stderr: "null",
    }).output()

    if (!output.success) return undefined

    const timestamp = textDecoder.decode(output.stdout).trim()
    return timestamp || undefined
  } catch {
    return undefined
  }
}

export const applyLastUpdatedFallback = (
  manifest: ModManifest,
  fallbackTimestamp: string | undefined,
  now: () => string = () => new Date().toISOString(),
): ModManifest => {
  if (manifest.last_updated) return manifest
  return {
    ...manifest,
    last_updated: fallbackTimestamp ?? now(),
  }
}

/**
 * Load all manifests from a directory.
 * Skips files starting with underscore (examples).
 */
export const loadManifests = async (
  manifestDir: string,
): Promise<ModManifest[]> => {
  const manifests: ModManifest[] = []
  const registryIndexDir = dirname(manifestDir)
  const history = await new Deno.Command("git", {
    args: ["-C", registryIndexDir, "rev-parse", "--is-shallow-repository"],
    stdout: "piped",
    stderr: "piped",
  }).output()
  if (!history.success) {
    throw new Error(`Cannot check Git history for ${registryIndexDir}`)
  }
  if (textDecoder.decode(history.stdout).trim() === "true") {
    throw new Error(
      `Git history for ${registryIndexDir} is shallow; fetch the full history before generating timestamps`,
    )
  }

  for await (
    const entry of walk(manifestDir, {
      exts: [".yaml", ".yml", ".json"],
      includeDirs: false,
      maxDepth: 1,
    })
  ) {
    // Skip example files
    if (entry.name.startsWith("_")) continue

    try {
      const content = await Deno.readTextFile(entry.path)
      const manifest = v.parse(ModManifest, YAML.parse(content))
      const manifestPath = relative(registryIndexDir, entry.path)
      const gitTimestamp = await getManifestGitTimestamp(registryIndexDir, manifestPath)
      manifests.push(applyLastUpdatedFallback(manifest, gitTimestamp))
    } catch (error) {
      console.error(`Error loading ${entry.path}: ${error}`)
    }
  }

  return manifests
}

/**
 * Generate combined JSON index.
 */
export const generateJsonIndex = (manifests: ModManifest[]): string => {
  const sorted = sortBy(manifests, (m) => m.display_name)
  // Keep the list payload small: omit previous release history here.
  const withoutHistory = sorted.map(({ previous_releases: _prev, ...rest }) => rest)
  return JSON.stringify(withoutHistory, null, 2) + "\n"
}

/**
 * Generate Markdown table of mods.
 */
export const generateMarkdownTable = (manifests: ModManifest[]): string => {
  const sorted = sortBy(manifests, (m) => m.display_name)

  let buffer = `# Cataclysm: Bright Nights Mod Registry

This is an automatically generated list of mods in the registry.

| | Name | Author | Version | Description |
|-|------|--------|---------|-------------|
`

  for (const mod of sorted) {
    const iconUrl = mod.icon_url ?? DEFAULT_ICON
    const downloadUrl = mod.source.url
    const description = mod.short_description.replace(/\|/g, "\\|").trim()

    buffer +=
      `| ![Icon](${iconUrl}) | [${mod.display_name}](${downloadUrl}) | ${mod.author} | ${mod.version} | ${description} |\n`
  }

  return buffer
}

/**
 * Generate OpenAPI 3.0 specification.
 */
export const generateOpenApiSpec = (): object => {
  const modSchema = toJsonSchema(ModManifest, { typeMode: "input", errorMode: "ignore" })

  // The list endpoint omits revision history to save bandwidth.
  const modIndexSchema = structuredClone(modSchema) as Record<string, unknown>
  const properties = (modIndexSchema as { properties?: Record<string, unknown> }).properties
  if (properties && "previous_releases" in properties) {
    delete properties.previous_releases
  }
  const required = (modIndexSchema as { required?: string[] }).required
  if (required) {
    ;(modIndexSchema as { required: string[] }).required = required.filter((k) =>
      k !== "previous_releases"
    )
  }

  return {
    openapi: "3.0.3",
    info: {
      title: "BN Mod Registry API",
      description:
        "API for accessing Cataclysm: Bright Nights mod metadata. This is a static JSON API - all data is served from pre-generated files.",
      version: "1.0.0",
      license: {
        name: "MIT",
        url: "https://opensource.org/licenses/MIT",
      },
    },
    servers: [
      {
        url: "https://cataclysmbn.github.io/registry",
        description: "Production",
      },
    ],
    paths: {
      "/generated/mods.json": {
        get: {
          summary: "Get all mods",
          description:
            "Returns an array of all mod manifests in the registry, sorted alphabetically by display name. Note: this list omits previous_releases to save bandwidth.",
          operationId: "getMods",
          tags: ["Mods"],
          responses: {
            "200": {
              description: "Successful response",
              content: {
                "application/json": {
                  schema: {
                    type: "array",
                    items: modIndexSchema,
                  },
                },
              },
            },
          },
        },
      },
      "/generated/mods/{mod_id}.json": {
        get: {
          summary: "Get a single mod",
          description: "Returns the manifest for a specific mod by its ID.",
          operationId: "getMod",
          tags: ["Mods"],
          parameters: [
            {
              name: "mod_id",
              in: "path",
              required: true,
              description: "The unique identifier of the mod",
              schema: {
                type: "string",
                pattern: "^[a-z0-9][a-z0-9_-]*$",
              },
            },
          ],
          responses: {
            "200": {
              description: "Successful response",
              content: {
                "application/json": {
                  schema: modSchema,
                },
              },
            },
            "404": {
              description: "Mod not found",
            },
          },
        },
      },
    },
    components: {
      schemas: {
        ModManifest: modSchema,
      },
    },
  }
}

/**
 * Generate all output files (JSON index, Markdown table, OpenAPI spec, and individual mod files).
 */
export const generateAll = async (
  manifestDir: string,
  outputDir: string,
): Promise<void> => {
  // Ensure output directories exist
  await Deno.mkdir(outputDir, { recursive: true })
  await Deno.mkdir(`${outputDir}/mods`, { recursive: true })

  console.log(`Loading manifests from ${manifestDir}/`)
  const manifests = await loadManifests(manifestDir)
  console.log(`Found ${manifests.length} manifests`)

  // Generate individual mod JSON files
  console.log(`Generating individual mod JSON files...`)
  await Promise.all(
    manifests.map((mod) =>
      Deno.writeTextFile(
        `${outputDir}/mods/${mod.id}.json`,
        JSON.stringify(mod, null, 2) + "\n",
      )
    ),
  )

  await Promise.all([
    Deno.writeTextFile(`${outputDir}/mods.json`, generateJsonIndex(manifests)),
    Deno.writeTextFile(`${outputDir}/mods.md`, generateMarkdownTable(manifests)),
    Deno.writeTextFile(
      `${outputDir}/mod_manifest.schema.json`,
      JSON.stringify(
        toJsonSchema(ModManifest, { typeMode: "input", errorMode: "ignore" }),
        null,
        2,
      ) + "\n",
    ),
    Deno.writeTextFile(
      `${outputDir}/openapi.json`,
      JSON.stringify(generateOpenApiSpec(), null, 2) + "\n",
    ),
  ])
}

// CLI entry point
if (import.meta.main) {
  await new Command()
    .name("generate")
    .version("1.0.0")
    .description("Generate index files from manifests (JSON and Markdown)")
    .arguments("[manifest-dir:string] [output-dir:string]")
    .action(
      async (
        _options,
        manifestDir = "registry-index/manifests",
        outputDir = "registry-index/generated",
      ) => {
        try {
          await generateAll(manifestDir, outputDir)
          console.log("\nDone!")
        } catch (error) {
          console.error(`Error: ${error}`)
          Deno.exit(1)
        }
      },
    )
    .parse(Deno.args)
}
